-- QA data is rolled back. Reuse existing identities; never change auth records.
begin;
select set_config('qa.diagnosis.owner',(select user_id::text from public.household_members where role='owner' order by joined_at limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('qa.diagnosis.owner'),true);
select set_config('qa.diagnosis.hh',public.create_household('QA financial diagnosis rollback')::text,true);
set local role authenticated;
do $$declare h uuid:=current_setting('qa.diagnosis.hh')::uuid;a uuid;b uuid;t uuid;v jsonb;before_count bigint;today date:=(statement_timestamp() at time zone 'America/Guatemala')::date;m date;future date;
begin
 m:=date_trunc('month',today)::date;future:=today+1;
 insert into public.finance_household_settings(household_id,split_method,updated_by) values(h,'income',auth.uid()) on conflict(household_id) do update set split_method='income';
 insert into public.finance_accounts(household_id,name,account_type,account_class,opening_balance,owner_user_id) values(h,'QA cash','checking','asset',1000,auth.uid()) returning id into a;
 insert into public.finance_accounts(household_id,name,account_type,account_class,opening_balance,owner_user_id,minimum_payment) values(h,'QA debt','loan','liability',500,auth.uid(),25) returning id into b;
 t:=public.quick_add_transaction(h,'Income',200,'income',m);update public.transactions set account_id=a where id=t;
 t:=public.quick_add_transaction(h,'Expense',50,'expense',m);update public.transactions set account_id=a where id=t;
 t:=public.quick_add_transaction(h,'Credit purchase',40,'expense',m);update public.transactions set account_id=b where id=t;
 t:=public.quick_add_transaction(h,'Credit payment',20,'income',m);update public.transactions set account_id=b where id=t;
 t:=public.quick_add_transaction(h,'Future income',9999,'income',future);update public.transactions set account_id=a where id=t;
 perform public.quick_add_transaction(h,'Previous expense',100,'expense',(m-interval '1 month')::date);
 insert into public.finance_transfers(household_id,from_account_id,to_account_id,amount,transfer_date,created_by) values(h,a,b,100,m,auth.uid());
 insert into public.finance_transfers(household_id,from_account_id,to_account_id,amount,transfer_date,created_by) values(h,a,b,999,future,auth.uid());
 select count(*) into before_count from public.transactions where household_id=h;
 v:=public.get_household_financial_diagnosis(h);
 if v->>'server_date'<>today::text or v->>'month'<>m::text or jsonb_array_length(v->'history')<>3 then raise exception 'Calendar/history mismatch';end if;
 if (select (item->>'balance')::numeric from jsonb_array_elements(v->'accounts') item where item->>'id'=a::text)<>1050 then raise exception 'Asset balance or future exclusion wrong';end if;
 if (select (item->>'balance')::numeric from jsonb_array_elements(v->'accounts') item where item->>'id'=b::text)<>420 then raise exception 'Liability balance wrong';end if;
 if (select sum((item->>'expense')::numeric) from jsonb_array_elements(v->'history') item)<>100 then raise exception 'History period wrong';end if;
 perform public.save_household_emergency_reserve(h,0,4);
 v:=public.get_household_financial_diagnosis(h);
 if (v->'reserve'->>'amount')::numeric<>0 or (v->'reserve'->>'target_months')::int<>4 or v->'reserve'->>'confirmed_on'<>today::text then raise exception 'Zero reserve/date missing';end if;
 if (select split_method from public.finance_household_settings where household_id=h)<>'income' then raise exception 'Reserve overwrote contribution rules';end if;
 if (select count(*) from public.transactions where household_id=h)<>before_count or (select count(*) from public.finance_transfers where household_id=h)<>2 then raise exception 'Diagnosis/reserve mutated ledger';end if;
 begin perform public.save_household_emergency_reserve(h,-1,3);raise exception 'Negative accepted';exception when check_violation then null;end;
 begin perform public.save_household_emergency_reserve(h,1.001,3);raise exception 'Fractional cent accepted';exception when check_violation then null;end;
 begin perform public.save_household_emergency_reserve(h,'NaN',3);raise exception 'NaN accepted';exception when check_violation then null;end;
 begin perform public.save_household_emergency_reserve(h,1,0);raise exception 'Zero months accepted';exception when check_violation then null;end;
 begin perform public.save_household_emergency_reserve(h,1,13);raise exception 'Thirteen months accepted';exception when check_violation then null;end;
 if public.build_household_backup_snapshot(h)->'tables'->'finance_household_settings'->0->>'emergency_fund_amount'<>'0.00' then raise exception 'Reserve missing from backup';end if;
end$$;
select true as balances_future_exclusion_history_reserve_rules_backup_and_ledger_passed;
rollback;

begin;
select set_config('qa.diagnosis.a',(select user_id::text from public.household_members where role='owner' order by joined_at limit 1),true);
select set_config('qa.diagnosis.b',(select user_id::text from public.household_members where role='owner' and user_id<>current_setting('qa.diagnosis.a')::uuid order by joined_at limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('qa.diagnosis.a'),true);
select set_config('qa.diagnosis.hh',public.create_household('QA financial diagnosis permissions rollback')::text,true);
select set_config('qa.diagnosis.other',public.create_household('QA financial diagnosis other rollback')::text,true);
insert into public.household_members(household_id,user_id,role) values(current_setting('qa.diagnosis.hh')::uuid,current_setting('qa.diagnosis.b')::uuid,'guest');
insert into public.household_member_access(household_id,user_id,module,access_level) select current_setting('qa.diagnosis.hh')::uuid,current_setting('qa.diagnosis.b')::uuid,module,'view' from unnest(array['health','finance','lists','documents','maintenance','meals']) module;
set local role authenticated;
select public.save_household_emergency_reserve(current_setting('qa.diagnosis.hh')::uuid,123,3);
select set_config('request.jwt.claim.sub',current_setting('qa.diagnosis.b'),true);
do $$declare h uuid:=current_setting('qa.diagnosis.hh')::uuid;begin
 if (public.get_household_financial_diagnosis(h)->'reserve'->>'amount')::numeric<>123 then raise exception 'View-only cannot read';end if;
 begin perform public.save_household_emergency_reserve(h,999,3);raise exception 'View-only write accepted';exception when insufficient_privilege then null;end;
 begin perform public.get_household_financial_diagnosis(current_setting('qa.diagnosis.other')::uuid);raise exception 'Other household exposed';exception when insufficient_privilege then null;end;
end$$;
reset role;
update public.household_member_access set access_level='none' where household_id=current_setting('qa.diagnosis.hh')::uuid and user_id=current_setting('qa.diagnosis.b')::uuid and module='finance';
set local role authenticated;
do $$begin begin perform public.get_household_financial_diagnosis(current_setting('qa.diagnosis.hh')::uuid);raise exception 'Hidden Finance exposed';exception when insufficient_privilege then null;end;end$$;
reset role;
update platform_security.household_controls set status='archived' where household_id=current_setting('qa.diagnosis.hh')::uuid;
select set_config('request.jwt.claim.sub',current_setting('qa.diagnosis.a'),true);
set local role authenticated;
do $$begin begin perform public.save_household_emergency_reserve(current_setting('qa.diagnosis.hh')::uuid,999,3);exception when insufficient_privilege then null;end;if (select emergency_fund_amount from public.finance_household_settings where household_id=current_setting('qa.diagnosis.hh')::uuid)<>123 then raise exception 'Archived write accepted';end if;end$$;
reset role;
set local role anon;
do $$begin begin perform public.get_household_financial_diagnosis(current_setting('qa.diagnosis.hh')::uuid);raise exception 'Anonymous read accepted';exception when insufficient_privilege then null;end;begin perform public.save_household_emergency_reserve(current_setting('qa.diagnosis.hh')::uuid,1,3);raise exception 'Anonymous write accepted';exception when insufficient_privilege then null;end;end$$;
select true as readonly_hidden_finance_cross_household_archived_and_anonymous_passed;
rollback;

begin;
select set_config('qa.diagnosis.owner',(select user_id::text from public.household_members where role='owner' order by joined_at limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('qa.diagnosis.owner'),true);
select set_config('qa.diagnosis.hh',public.create_household('QA financial diagnosis old backup rollback')::text,true);
set local role authenticated;
-- Restore a legacy settings record which predates the optional reserve fields.
select set_config('qa.diagnosis.snapshot',jsonb_set(public.build_household_backup_snapshot(current_setting('qa.diagnosis.hh')::uuid),'{tables,finance_household_settings}',jsonb_build_array(jsonb_build_object('household_id',current_setting('qa.diagnosis.hh'),'split_method','custom','updated_by',auth.uid(),'updated_at',now())))::text,true);
select set_config('qa.diagnosis.backup',public.import_household_backup(current_setting('qa.diagnosis.hh')::uuid,current_setting('qa.diagnosis.snapshot')::jsonb,'QA financial diagnosis old backup rollback')::text,true);
select public.restore_household_backup_missing(current_setting('qa.diagnosis.backup')::uuid);
do $$begin if (select split_method from public.finance_household_settings where household_id=current_setting('qa.diagnosis.hh')::uuid)<>'custom' then raise exception 'Legacy settings restore failed';end if;if public.get_household_financial_diagnosis(current_setting('qa.diagnosis.hh')::uuid)->'reserve'->>'amount' is not null then raise exception 'Legacy reserve invented';end if;end$$;
select true as legacy_backup_restore_passed;
rollback;
